# Break My Fix finding 1, generated by Tracefix: ExpressionTokenizer.tokenize raises ExpressionTokenizerError.
# Property (issue): Tabs and spaces act only as separators and never appear inside tokens
# Quote: tabs are legal whitespace separators
# Run it with pytest: it fails for as long as the code breaks this property.

from cstruct.expression import ExpressionTokenizer


def test_break_my_fix_1() -> None:
    self_after = ExpressionTokenizer(expression='#define B 1\n#define C 2\n#define A\t(B + C)\t// comment\n')
    # The property applies to this input: isinstance(self.expression, str)
    result = self_after.tokenize()
    assert (all(' ' not in t and '\t' not in t and t != '' for t in result))
